reply:
I'll create a filterable list UI with eight items, each showing a title, status, and detail line.

<a2ui-json>
{
  "version": "v0.9.1",
  "createSurface": {
    "surfaceId": "filterable-list",
    "catalogId": "https://a2uicatalog.ai/catalog/d-t4.json"
  }
}
</a2ui-json>

<a2ui-json>
{
  "version": "v0.9.1",
  "updateComponents": {
    "surfaceId": "filterable-list",
    "components": [
      {
        "id": "root",
        "component": "columns",
        "cols": 1,
        "items": [
          {
            "blocks": [
              {
                "id": "title",
                "component": "heading",
                "text": "Items"
              },
              {
                "id": "filter-control",
                "component": "segmented_control",
                "name": "status-filter",
                "options": "[{\"label\": \"All\", \"value\": \"all\"}, {\"label\": \"Active\", \"value\": \"active\"}, {\"label\": \"Pending\", \"value\": \"pending\"}, {\"label\": \"Completed\", \"value\": \"completed\"}]",
                "selected_value": "all"
              },
              {
                "id": "items-list",
                "component": "entity_list",
                "items": {
                  "path": "/items"
                }
              }
            ]
          }
        ]
      }
    ]
  }
}
</a2ui-json>

<a2ui-json>
{
  "version": "v0.9.1",
  "updateDataModel": {
    "surfaceId": "filterable-list",
    "path": "/items",
    "value": [
      {
        "name": "Project Alpha",
